#!/usr/bin/env python3
"""Tropical Graph Hodge Theory: Applications Demo (self-contained)"""

from collections import defaultdict
from typing import List, Set, Tuple, Dict, Optional

class SimpleGraph:
    def __init__(self, n, edges):
        self.n = n
        self.adj = defaultdict(set)
        self.edges = set()
        for u, v in edges:
            if u != v:
                self.adj[u].add(v)
                self.adj[v].add(u)
                self.edges.add((min(u, v), max(u, v)))

    def connected_components(self, vertex_set=None):
        if vertex_set is None:
            vertex_set = set(range(self.n))
        visited = set()
        components = []
        for v in sorted(vertex_set):
            if v not in visited:
                comp = set()
                stack = [v]
                while stack:
                    u = stack.pop()
                    if u in visited or u not in vertex_set:
                        continue
                    visited.add(u)
                    comp.add(u)
                    for w in self.adj[u]:
                        if w in vertex_set and w not in visited:
                            stack.append(w)
                components.append(comp)
        return components

    def edge_count_induced(self, S):
        return sum(1 for u, v in self.edges if u in S and v in S)

def compute_cycle_rank(G, S):
    if not S: return 0
    return G.edge_count_induced(S) - len(S) + len(G.connected_components(S))

def q_visible_count(G, q, S):
    if not S: return 0
    return sum(1 for comp in G.connected_components(S) if any(q in G.adj[v] for v in comp))

def predicted_dim(G, q, S):
    return compute_cycle_rank(G, S) + q_visible_count(G, q, S)

# Network robustness demo
print("=== Network Robustness Analysis ===")
star = SimpleGraph(5, [(0,1),(0,2),(0,3),(0,4)])
ring = SimpleGraph(5, [(0,1),(1,2),(2,3),(3,4),(4,0)])
mesh = SimpleGraph(5, [(0,1),(0,2),(0,3),(0,4),(1,2),(2,3),(3,4),(4,1)])
S = {1,2,3,4}
for name, G in [("Star", star), ("Ring", ring), ("Mesh", mesh)]:
    b = compute_cycle_rank(G, S)
    k = q_visible_count(G, 0, S)
    print(f"  {name}: beta1={b}, kappa={k}, dim={b+k}")

